class ChinaProvince {
  const ChinaProvince({required this.name, required this.d, required this.cx, required this.cy});
  final String name;
  final String d;
  final double cx;
  final double cy;
}

class ChinaMapProj {
  static const double vbW = 900;
  static const double vbH = 680;
  static const double lonMin = 73.0;
  static const double lonMax = 135.2;
  static const double latMin = 17.8;
  static const double latMax = 53.7;
  static const double pad = 12.0;

  static OffsetLonLat project(double lon, double lat) {
    final x = pad + (lon - lonMin) / (lonMax - lonMin) * (vbW - 2 * pad);
    final y = pad + (latMax - lat) / (latMax - latMin) * (vbH - 2 * pad);
    return OffsetLonLat(x, y);
  }
}

class OffsetLonLat {
  const OffsetLonLat(this.x, this.y);
  final double x;
  final double y;
}

